import React from 'react';
import { Pie } from 'react-chartjs-2';

function RiskChart({ risks }) {
  // Count risks by status
  const statusCounts = {
    Open: risks.filter(r => r.status === 'Open').length,
    'In Progress': risks.filter(r => r.status === 'In Progress').length,
    Resolved: risks.filter(r => r.status === 'Resolved').length,
  };

  const data = {
    labels: ['Open', 'In Progress', 'Resolved'],
    datasets: [
      {
        data: [statusCounts.Open, statusCounts['In Progress'], statusCounts.Resolved],
        backgroundColor: ['#f87171', '#fbbf24', '#34d399'], // red, yellow, green
      },
    ],
  };

  return (
    <div style={{ width: '400px', marginTop: '20px' }}>
      <h2>Risks by Status</h2>
      <Pie data={data} />
    </div>
  );
}

export default RiskChart;
